mapper.select:
SELECT id, conversation_id, content, created_at FROM ( SELECT id, conversation_id, content, created_at, ROW_NUMBER() OVER ( PARTITION BY conversation_id ORDER BY sequence_no DESC, id DESC ) AS rn FROM group_chat_message WHERE conversation_id IN
#{conversationId}
AND visibility = 'public' AND status = 'completed' ) latest WHERE rn = 1
